head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getRowVisible]<br/>Body Row 의 인덱스를 사용하여 특정 Body Row 의 숨김(Visible) 여부를 반환합니다.",
    "validation" : [
        "rowIndex(필수) 파라미터로 숨김 여부를 조회할 Body Row 의 인덱스를 설정할 수 있어야 합니다.",
        "rowIndex(필수) 파라미터의 Row 인덱스는 0 부터 시작하며 바인딩 된 DataList 기준으로 인덱스가 설정됩니다.",
        "반환값은 해당 Row 가 표시된 상태이면 true 입니다.",
        "반환값은 해당 Row 가 숨겨진 상태이면 false 입니다.",
        "파라미터에 유효하지 않은 값을 설정하면 false 를 반환합니다.",
        "Row 가 숨겨지면 RowNum Column 의 Row 순번은 재계산되지 않고 숨겨진 Row 의 순번은 건너뜁니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 바인딩 DataList 생성 (6 Row)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="name1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="name2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col3" name="name3" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true">';
    let arrNames = ['김철수', '이영희', '박민준', '최서연', '정도윤', '강하은'];
    let arrDept = ['영업1팀', '영업2팀', '개발팀', '인사팀', '재무팀', '기획팀'];
    for (var i = 0; i < arrNames.length; i++) {
        strDlt += '<w2:row>';
        strDlt += '<col1><![CDATA[' + (i + 1) + ']]></col1>';
        strDlt += '<col2><![CDATA[' + arrNames[i] + ']]></col2>';
        strDlt += '<col3><![CDATA[' + arrDept[i] + ']]></col3>';
        strDlt += '</w2:row>';
    }
    strDlt += '</w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 조건 설정 - RowNum Column 표시 (@spec 순번 검증용)
    let properties = {
        dataList: "data:dlt_bind",
        rowNumVisible: "true",
    };

    let cList = $c.gcm.createCList(properties);

    // 테스트 참고 라벨 (검증 운영 정보) — grp_comp 맨 위에 표시되도록 grid 생성 전에 먼저 생성
    $c.gcm.createLabel('label="[전제] Row 1 (이영희) 을 초기에 숨김 처리 -> false 확인용\n[절차] rowIndex 선택 후 (getRowVisible 조회) 클릭 (필요 시 (setRowVisible 적용) 으로 추가 숨김/표시)\n[확인] 표시 Row=true / 숨김 Row=false / 유효하지 않은 값(99)=false, 표시중 RowNum 순번은 숨김 순번을 건너뜀"', '', 'label1');

    // target 생성
    await scwin.createGrid(cList);

    // 초기 숨김 상태 만들기 : Row 1 숨김 (getRowVisible 의 false 케이스 확보)
    target1.setRowVisible(1, false);
}



// 일반 그리드(custom 셀 불필요) 동적 생성
scwin.createGrid = async function (cList) {
    let grp_comp = $c.gcm.getTestGroup('');

    let strTarget = '';
    strTarget += '<w2:gridView ' + $c.gcm.strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:500px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="사원 목록"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="80" style="" inputType="text" id="hcol1" value="사번"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="이름"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol3" value="부서"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="80" style="" inputType="text" id="col1" displayType="label"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col2" displayType="label"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col3" displayType="label"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 숨김/표시 상태를 만드는 보조 버튼 (getRowVisible 의 true/false 케이스 확보용)
scwin.btn_setRowVisible_onclick = function () {
    let rowIndex = Number(par_rowIndex.getText());
    let visibleStr = par_visible.getText();

    let visBool = visibleStr === 'true';
    target1.setRowVisible(rowIndex, visBool);

    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("setRowVisible(" + rowIndex + ", " + visBool + ") 적용 완료");
    }, 300);
}



// getRowVisible 조회 (메인 검증)
scwin.btn_getRowVisible_onclick = function () {
    let rowIndex = Number(par_rowIndex.getText());

    // getRowVisible : 해당 Row 의 숨김 여부 반환 (표시=true / 숨김=false / 유효하지 않은 값=false)
    let isVisible = target1.getRowVisible(rowIndex);

    wf_body_bottom.getObj("scwin").setReturnValue("[getRowVisible(" + rowIndex + ")] " + isVisible);
}
